def transform(grid):
    h, w = len(grid), len(grid[0])
    frames = []

    for color in range(1, 10):
        best = None
        best_area = 0
        for top in range(h):
            for bottom in range(top + 2, h):
                for left in range(w):
                    for right in range(left + 2, w):
                        if (grid[top][left] != color or grid[top][right] != color or
                            grid[bottom][left] != color or grid[bottom][right] != color):
                            continue
                        if not all(grid[top][c] == color and grid[bottom][c] == color
                                   for c in range(left, right + 1)):
                            continue
                        if not all(grid[r][left] == color and grid[r][right] == color
                                   for r in range(top, bottom + 1)):
                            continue
                        area = (bottom - top + 1) * (right - left + 1)
                        if area > best_area:
                            best = (top, left, bottom, right, color)
                            best_area = area
        if best:
            frames.append(best)

    if not frames:
        return [row[:] for row in grid]

    def interior_count(frame):
        top, left, bottom, right, color = frame
        return sum(grid[r][c] == color
                   for r in range(top + 1, bottom)
                   for c in range(left + 1, right))

    source = max(frames, key=interior_count)
    st, sl, sb, sr, sc = source
    pattern = [
        [grid[r][c] == sc for c in range(sl + 1, sr)]
        for r in range(st + 1, sb)
    ]
    out = [row[:] for row in grid]

    for frame in frames:
        top, left, bottom, right, color = frame
        if frame == source:
            continue
        if (bottom - top == sb - st and right - left == sr - sl):
            for dr in range(1, bottom - top):
                for dc in range(1, right - left):
                    out[top + dr][left + dc] = color if pattern[dr - 1][dc - 1] else 0
        else:
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    out[r][c] = 0

    return out
